L386: fn escape_xml_text(value: &str) -> String {
L387:     let mut escaped = String::with_capacity(value.len());
L388:     for ch in value.chars() {
L389:         match ch {
L390:             '&' => escaped.push_str("&amp;"),
L391:             '<' => escaped.push_str("&lt;"),
L392:             '>' => escaped.push_str("&gt;"),
L393:             '"' => escaped.push_str("&quot;"),
L394:             '\'' => escaped.push_str("&apos;"),
L395:             _ => escaped.push(ch),
L396:         }
L397:     }
L398:     escaped
L399: }
L400: fn append_hook_events(
L401:     handlers: &mut Vec<ConfiguredHandler>,
L402:     hook_entries: &mut Vec<HookListEntry>,
L403:     warnings: &mut Vec<String>,
L404:     display_order: &mut i64,
L405:     source: HookHandlerSource<'_>,
L406:     hook_events: HookEventsToml,
L407:     policy: HookDiscoveryPolicy,
L408: ) {
L409:     if !policy.allows(&source) {
L410:         return;
L411:     }
L412:     for (event_name, groups) in hook_events.into_matcher_groups() {
L413:         append_matcher_groups(
L414:             handlers,
L415:             hook_entries,
L416:             warnings,
L417:             display_order,
L418:             &source,
L419:             event_name,
L420:             groups,
L421:         );
L422:     }
L423: }
L424: fn append_matcher_groups(
L425:     handlers: &mut Vec<ConfiguredHandler>,
L426:     hook_entries: &mut Vec<HookListEntry>,
L427:     warnings: &mut Vec<String>,
L428:     display_order: &mut i64,
L429:     source: &HookHandlerSource<'_>,
L430:     event_name: codex_protocol::protocol::HookEventName,
L431:     groups: Vec<MatcherGroup>,
L432: ) {
L433:     for (group_index, group) in groups.into_iter().enumerate() {
L434:         let matcher = matcher_pattern_for_event(event_name, group.matcher.as_deref());
L435:         if let Some(matcher) = matcher
L436:             && let Err(err) = validate_matcher_pattern(matcher)
L437:         {
L438:             warnings.push(format!(
L439:                 "invalid matcher {matcher:?} in {}: {err}",
L440:                 source.path.display()
L441:             ));
L442:             continue;
L443:         }
L444:         for (handler_index, handler) in group.hooks.iter().cloned().enumerate() {
L445:             let normalized = match handler {
L446:                 HookHandlerConfig::Command {
L447:                     command,
L448:                     command_windows,
L449:                     timeout_sec,
L450:                     r#async,
L451:                     status_message,
L452:                     additional_context_limit,
L453:                 } => {
L454:                     let command = if cfg!(windows) {
L455:                         command_windows.unwrap_or(command)
L456:                     } else {
L457:                         command
L458:                     };
L459:                     if command.trim().is_empty() {
L460:                         warnings.push(format!(
L461:                             "skipping empty hook command in {}",
L462:                             source.path.display()
L463:                         ));
L464:                         continue;
L465:                     }
L466:                     let timeout_sec = normalize_command_hook(
L467:                         event_name,
L468:                         timeout_sec,
L469:                         source.path.as_path(),
L470:                         warnings,
L471:                     );
L472:                     let runs_async = r#async
L473:                         && event_name != codex_protocol::protocol::HookEventName::SessionEnd;
L474:                     if r#async && !runs_async {
L475:                         warnings.push(format!(
L476:                             "running async SessionEnd hook synchronously in {}",
L477:                             source.path.display()
L478:                         ));
L479:                     }
L480:                     let additional_context_limit = if matches!(
L481:                         event_name,
L482:                         codex_protocol::protocol::HookEventName::PreToolUse
L483:                             | codex_protocol::protocol::HookEventName::PostToolUse
L484:                             | codex_protocol::protocol::HookEventName::SessionStart
L485:                             | codex_protocol::protocol::HookEventName::UserPromptSubmit
L486:                             | codex_protocol::protocol::HookEventName::SubagentStart
L487:                     ) {
L488:                         additional_context_limit
L489:                     } else {
L490:                         if additional_context_limit.is_some() {
L491:                             warnings.push(format!(
L492:                                 "ignoring additionalContextLimit for {event_name:?} hook in {}: this event cannot emit additionalContext",
L493:                                 source.path.display()
L494:                             ));
L495:                         }
L496:                         None
L497:                     };
L498:                     let normalized_additional_context_limit = additional_context_limit
L499:                         .filter(|limit| *limit != DEFAULT_HOOK_OUTPUT_TOKEN_LIMIT);
L500:                     let config = HookHandlerConfig::Command {
L501:                         command: command.clone(),
L502:                         command_windows: None,
L503:                         timeout_sec: Some(timeout_sec),
L504:                         r#async,
L505:                         status_message: status_message.clone(),
L506:                         additional_context_limit: normalized_additional_context_limit,
L507:                     };
L508:                     let command = source.env.iter().fold(command, |command, (key, value)| {
L509:                         command.replace(&format!("${{{key}}}"), value)
L510:                     });
L511:                     NormalizedHandler {
L512:                         config,
L513:                         kind: ConfiguredHandlerKind::Command {
L514:                             command,
L515:                             env: source.env.clone(),
L516:                             r#async: runs_async,
L517:                         },
L518:                         timeout_sec,
L519:                         status_message,
L520:                         additional_context_limit,
L521:                     }
L522:                 }
L523:                 HookHandlerConfig::McpTool { .. } => {
L524:                     warnings.push(format!(
L525:                         "skipping MCP tool hook in {}: MCP tool hooks are not supported yet",
L526:                         source.path.display()
L527:                     ));
L528:                     continue;
L529:                 }
L530:                 HookHandlerConfig::Prompt {} => {
L531:                     warnings.push(format!(
L532:                         "skipping prompt hook in {}: prompt hooks are not supported yet",
L533:                         source.path.display()
L534:                     ));
L535:                     continue;
L536:                 }
L537:                 HookHandlerConfig::Agent {} => {
L538:                     warnings.push(format!(
L539:                         "skipping agent hook in {}: agent hooks are not supported yet",
L540:                         source.path.display()
L541:                     ));
L542:                     continue;
L543:                 }
L544:             };
L545:             let NormalizedHandler {
L546:                 config,
L547:                 kind,
L548:                 timeout_sec,
L549:                 status_message,
L550:                 additional_context_limit,
L551:             } = normalized;
L552:             let current_hash = hook_hash(event_name, matcher, &group, config);
L553:             let key = crate::hook_key(&source.key_source, event_name, group_index, handler_index);
L554:             let state = source.hook_states.get(&key);
L555:             let enabled = hook_enabled(source.is_managed, state);
L556:             let trusted_hash = hook_trusted_hash(source.is_managed, state);
L557:             let trust_status = hook_trust_status(source.is_managed, &current_hash, trusted_hash);
L558:             let ConfiguredHandlerKind::Command { command, .. } = &kind;
L559:             let execution_mode =
L560:                 if matches!(kind, ConfiguredHandlerKind::Command { r#async: true, .. }) {
L561:                     HookExecutionMode::Async
L562:                 } else {
L563:                     HookExecutionMode::Sync
L564:                 };
L565:             hook_entries.push(HookListEntry {
L566:                 key,
L567:                 event_name,
L568:                 handler_type: HookHandlerType::Command,
L569:                 matcher: matcher.map(ToOwned::to_owned),
L570:                 command: Some(command.clone()),
L571:                 timeout_sec,
L572:                 status_message: status_message.clone(),
L573:                 additional_context_limit,
L574:                 source_path: source.path.clone(),
L575:                 source: source.source,
L576:                 plugin_id: source.plugin_id.clone(),
L577:                 display_order: *display_order,
L578:                 enabled,
L579:                 is_managed: source.is_managed,
L580:                 current_hash,
L581:                 trust_status,
L582:                 execution_mode,
L583:             });
L584:             if enabled
L585:                 && (source.bypass_hook_trust
L586:                     || matches!(
L587:                         trust_status,
L588:                         HookTrustStatus::Managed | HookTrustStatus::Trusted
L589:                     ))
L590:             {
L591:                 handlers.push(ConfiguredHandler {
L592:                     event_name,
L593:                     matcher: matcher.map(ToOwned::to_owned),
L594:                     timeout_sec,
L595:                     status_message,
L596:                     additional_context_limit: AdditionalContextLimit::from_config(
L597:                         additional_context_limit,
L598:                     ),
L599:                     source_path: source.path.clone(),
L600:                     source: source.source,
L601:                     display_order: *display_order,
L602:                     kind,
L603:                 });
L604:             }
L605:             *display_order += 1;
L606:         }
L607:     }
L608: }
L609: /// Normalizes command-hook timeouts. SessionEnd defaults to one second and is capped at three
L610: /// seconds; all other command hooks keep the standard ten-minute default.
L611: fn normalize_command_hook(
L612:     event_name: codex_protocol::protocol::HookEventName,
L613:     timeout_sec: Option<u64>,
L614:     source_path: &Path,
L615:     warnings: &mut Vec<String>,
L616: ) -> u64 {
L617:     if event_name != codex_protocol::protocol::HookEventName::SessionEnd {
L618:         return timeout_sec.unwrap_or(600).max(1);
L619:     }
L620:     let max_timeout_sec = SESSION_END_MAX_TIMEOUT_SEC;
L621:     if timeout_sec.is_some_and(|timeout_sec| timeout_sec > max_timeout_sec) {
L622:         warnings.push(format!(
L623:             "clamping SessionEnd hook timeout to {max_timeout_sec}s in {}",
L624:             source_path.display()
L625:         ));
L626:     }
L627:     timeout_sec
L628:         .unwrap_or(SESSION_END_DEFAULT_TIMEOUT_SEC)
L629:         .clamp(1, max_timeout_sec)
L630: }
L631: /// Hash a normalized, config-derived identity instead of source text so equivalent
L632: /// hooks from config TOML and hooks.json converge on the same trust identity.
L633: #[derive(Serialize)]
L634: struct NormalizedHookIdentity {
L635:     event_name: &'static str,
L636:     #[serde(flatten)]
L637:     group: MatcherGroup,
L638: }
L639: fn hook_hash(
L640:     event_name: codex_protocol::protocol::HookEventName,
L641:     matcher: Option<&str>,
L642:     group: &MatcherGroup,
L643:     normalized_handler: HookHandlerConfig,
L644: ) -> String {
L645:     let mut group = group.clone();
L646:     group.matcher = matcher.map(ToOwned::to_owned);
L647:     group.hooks = vec![normalized_handler];
L648:     let identity = NormalizedHookIdentity {
L649:         event_name: crate::hook_event_key_label(event_name),
L650:         group,
L651:     };
L652:     let Ok(value) = TomlValue::try_from(identity) else {
L653:         unreachable!("normalized hook identity should serialize to TOML");
L654:     };
L655:     version_for_toml(&value)
L656: }
L657: fn hook_trust_status(
L658:     is_managed: bool,
L659:     current_hash: &str,
L660:     trusted_hash: Option<&str>,
L661: ) -> HookTrustStatus {
L662:     if is_managed {
L663:         HookTrustStatus::Managed
L664:     } else {
L665:         match trusted_hash {
L666:             Some(trusted_hash) if trusted_hash == current_hash => HookTrustStatus::Trusted,
L667:             Some(_) => HookTrustStatus::Modified,
L668:             None => HookTrustStatus::Untrusted,
L669:         }
L670:     }
L671: }
L672: fn hook_enabled(is_managed: bool, state: Option<&HookStateToml>) -> bool {
L673:     is_managed || state.and_then(|state| state.enabled) != Some(false)
L674: }
L675: 
L676: fn hook_trusted_hash(is_managed: bool, state: Option<&HookStateToml>) -> Option<&str> {
L677:     (!is_managed)
L678:         .then(|| state.and_then(|state| state.trusted_hash.as_deref()))
L679:         .flatten()
L680: }
L681: fn hook_metadata_for_config_layer_source(source: &ConfigLayerSource) -> (HookSource, bool) {
L682:     match source {
L683:         ConfigLayerSource::PackagedDefaults { .. } => (HookSource::Unknown, false),
L684:         ConfigLayerSource::System { .. } => (HookSource::System, true),
L685:         ConfigLayerSource::User { .. } => (HookSource::User, false),
L686:         ConfigLayerSource::Project { .. } => (HookSource::Project, false),
L687:         ConfigLayerSource::Mdm { .. } => (HookSource::Mdm, true),
L688:         ConfigLayerSource::EnterpriseManaged { .. } => (HookSource::CloudManagedConfig, true),
L689:         ConfigLayerSource::SessionFlags => (HookSource::SessionFlags, false),
L690:         ConfigLayerSource::LegacyManagedConfigTomlFromFile { .. } => {
L691:             (HookSource::LegacyManagedConfigFile, true)
L692:         }
L693:         ConfigLayerSource::LegacyManagedConfigTomlFromMdm => {
L694:             (HookSource::LegacyManagedConfigMdm, true)
L695:         }
L696:     }
L697: }
L698: fn hook_source_for_requirement_source(source: Option<&RequirementSource>) -> HookSource {
L699:     match source {
L700:         Some(RequirementSource::MdmManagedPreferences { .. }) => HookSource::Mdm,
L701:         Some(RequirementSource::SystemRequirementsToml { .. }) => HookSource::System,
L702:         Some(RequirementSource::LegacyManagedConfigTomlFromFile { .. }) => {
L703:             HookSource::LegacyManagedConfigFile
L704:         }
L705:         Some(RequirementSource::LegacyManagedConfigTomlFromMdm) => {
L706:             HookSource::LegacyManagedConfigMdm
L707:         }
L708:         Some(RequirementSource::Composite { sources }) => {
L709:             // Requirements hook composition preserves contributing sources in
L710:             // priority order, but discovery only carries one source for the
L711:             // whole merged hooks field. Use the primary contributor as the best
L712:             // available coarse attribution.
L713:             hook_source_for_requirement_source(sources.first())
L714:         }
L715:         Some(RequirementSource::EnterpriseManaged { .. }) => HookSource::CloudRequirements,
L716:         Some(RequirementSource::Unknown) | None => HookSource::Unknown,
L717:     }
L718: }
